from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA01B,0xA01C,'data','Chiarimento: offset fisico del gruppo da completare'),(0xA040,0xA048,'code','Avvio: azzeramento esplicito del chiarimento'),(0xAAC4,0xAAD1,'code','Parser: ingresso durante un chiarimento pendente'),(0xAD6C,0xADD4,'code','Continuazione: copia nel vecchio nodo o sostituzione con nuovo verbo'),(0xB244,0xB259,'code','Selezione: zero candidati, scelta unica o domanda'),(0xC792,0xC7A6,'code','Restrizione morbida: accetta in preflight, rifiuta in esecuzione'),(0xC7BB,0xC7E4,'code','Classe9: controlli rigidi e proprietà rinviata alla fase esecutiva'),(0xDCA2,0xDCC1,'code','TAKE: possesso già acquisito, ciclo di contenimento e handler'),(0xB447,0xB468,'code','Ruoli degli argomenti: offset08/12 distinti dall’ordine semantico'),(0xB5B6,0xB5D3,'code','Domanda: salva offset e trattiene il nodo originale'),(0xB5D3,0xB5FC,'code','Domande: distinzione fra WHICH e WHAT per i due ruoli'),(0xB5FC,0xB62F,'code','WHAT sul primo o secondo argomento: offset prima del testo'),(0xD78E,0xD7B2,'code','Ritorno del parser: azzera il chiarimento anche in caso di errore'),(0xD99E,0xD9B7,'code','Ripetizione @: durante un chiarimento torna all’editor')]
notes={0xB250:'La domanda dipende dal numero dei candidati: uno viene scelto, più di uno porta al dispatch WHAT/WHICH. Non chiedere sempre un nome quando manca il primo gruppo.',0xC79A:'A00B=0: una restrizione morbida non scarta il referente dalla ricerca. In esecuzione ritorna l’handler CB7B. La restrizione di possesso altrui nella classe9 arriva a questo controllo.',0xC7BB:'Classe9: percezione, record singolo, non-persona e capacità sono controllati prima del possesso altrui. Per questo un oggetto troppo pesante non diventa candidato solo perché tenuto da un NPC.',0xC7DF:'C8AF individua un antenato persona: il relativo rifiuto passa dal controllo morbido C768/C79A. Il giornale tenuto da Watson conta fra i candidati di TAKE, pur venendo rifiutato durante l’esecuzione.',0xDCA2:'D26C verifica se il referente è già posseduto dall’attore corrente: quel caso usa il diverso handler DCBB. Non confonderlo con la restrizione morbida per il possesso da parte di un altro NPC.',0xDCA7:'Invertendo A e il riferimento HL rispetto a D26C, verifica se l’attore è contenuto nel referente: evita di prendere il proprio contenitore. Il peso è controllato prima, dalla classe9.',0xDCBB:'Handler del caso già posseduto: chiama il testo68B7. I rifiuti specifici e quelli generici non vanno tutti eliminati dal preflight.',0xB5D3:'Per il secondo ruolo legge la presenza del nome in B16E. Se manca, usa WHAT aB610; se è presente ma ambiguo, costruisce WHICH.',0xB5E2:'Per il primo ruolo legge B16D. Il nome assente porta aB5FC; il nome ambiguo conserva l’offset B182 per WHICH.',0xB5F2:'Anche WHICH passa dal medesimo B5B6, che conserva nodo e offset prima di stampare6888.',0xA01B:'Byte mutabile:0 nessun chiarimento;08 e12 esadecimali sono offset8 e18 decimali dei referenti nei due gruppi del nodo. Non è un booleano né il puntatore del nodo, custodito separatamente a9FF0.',0xA044:'Scrittura all’avvio, prima del ciclo di input. Il modello inizializza logicamente a0; LOAD vecchi senza campo non riceve un fallback di boot.',0xAAC4:'Legge il valore precedente durante il parsing della risposta. Non azzerare A01B all’ingresso AAB2: D793 lo azzera soltanto al ritorno.',0xAACC:'Una continuazione forza il modo comando e permette la frase nominale senza verbo.',0xAD6C:'Controlla il chiarimento ancora attivo prima del reset esterno D793. Il vecchio nodo è a9FF0.',0xAD81:'Un verbo nella nuova frase sostituisce il vecchio comando: non si tratta di una precisazione nominale.',0xAD83:'A01B è un offset nel nodo fisico originale. Il riordino semantico JavaScript dei complementi non deve cambiare lo slot da completare.',0xAD95:'Il campo da completare si ottiene sommando l’offset al vecchio nodo. Una risposta completa i campi disponibili senza perdere il comando precedente.',0xADB8:'Con nuovo verbo la continuazione precedente viene abbandonata; il reset D793 rimane necessario anche se poi il comando fallisce.',0xADD1:'Rilascia il nodo non più necessario dopo copia o sostituzione. Le prove confrontano anche tutti i residui del pool.',0xB447:'Bit5 del modello decide l’associazione dei due ruoli agli offset fisici. La posizione semantica di un oggetto non basta a ricostruire il byte.',0xB449:'Una disposizione usa08/12; l’altra le scambia. Nei comandi con complemento iniziale il referente principale può trovarsi nel secondo gruppo fisico.',0xB5B6:'Scrive l’offset prima di trattenere il nodo e prima del testo della domanda. SAVE può attraversare0 e porre di nuovo lo stesso chiarimento.',0xB5BD:'Il primo nodo passa dalla lista eseguibile alla lista pendente; il collegamento viene troncato, non ricostruito da un AST finale.',0xB603:'WHAT del primo ruolo: usa B182, cioè l’offset fisico preparato per quel ruolo. Può essere08 o12 in base all’ordine dei complementi.',0xB622:'WHAT del secondo ruolo: usa B183. Anche un referente omesso può trattenere il comando. Gli altri argomenti univoci possono invece risolversi implicitamente.',0xD78E:'Unico ingresso ordinario del parser principale. Il parsing delle citazioni segue il proprio percorso: non aggiungere un reset D793 a ogni chiamata interna AAB2.',0xD793:'Reset dopo il ritorno, sia riuscito sia fallito; PUSH/POP AF conserva l’esito del parser. Errori lessicali precedenti non raggiungono questa scrittura.',0xD7AC:'Reset del riuso del buffer dopo una normale unità riuscita; non confonderlo con il byte del chiarimento.',0xD99E:'@ durante chiarimento non ripete il comando e non entra nel parser: A01B conserva il valore. Una vera risposta vuota entra invece e può azzerare/porre di nuovo la domanda.',0xD9A7:'Senza chiarimento @ seleziona il riuso del buffer; questo flag D714 ha un ciclo distinto.'}
lines=['; Analisi offline, dati distinti dal codice; nessuna esecuzione Z80 nel motore JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=b-at;op='DEFB '+','.join(f'${v:02X}'for v in m[at:b])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/clarification-offset';root.mkdir(exist_ok=True)
(root/'clarification-offset.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=122 if k=='data'else 92,**({'fields':[['A01B','1 byte','0 / 08 / 12 esadecimale: nessun chiarimento oppure offset del referente nel nodo originale'],['Distinto da','9FF0 e slot semantico','Il puntatore del nodo e il riordino degli argomenti hanno stato separato']]}if k=='data'else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
